_INTL_CACHE = None


def _norm(name: str) -> str:
    s = (name or "").strip().replace(u"《", "").replace(u"》", "")
    s = re.sub(r"[\s\u3000]+", "", s).replace(u"·", "").replace(".", "")
    s = re.sub(r"\([^)]*\)$", "", s)
    return s


_INTL_STOP = ("and", "the", "of", "for", "in", "on", "a", "an", "de", "la", "le", "und", "et")


def _intl_key(name: str) -> str:
    """国际刊名归一化：小写、& → and、去掉虚词与符号。
    这样 `Computers & Education` 与 SJR 里的 `Computers and Education` 能对上。"""
    s = (name or "").lower().replace("&", " and ")
    words = re.sub(r"[^a-z0-9]+", " ", s).split()
    return "".join(w for w in words if w not in _INTL_STOP)


def _intl():
    global _INTL_CACHE
    if _INTL_CACHE is None:
        _INTL_CACHE = {}
        p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "intl_sjr.csv")
        try:
            with open(p, encoding="utf-8", newline="") as f:
                rd = csv.reader(f)
                next(rd, None)
                for row in rd:
                    if len(row) >= 2:
                        _INTL_CACHE[row[0]] = int(row[1])
        except Exception:
            _INTL_CACHE = {}
    return _INTL_CACHE


def tier_of(journal_name: str) -> int:
    """返回分级码（见模块 docstring）。中文名录精确匹配；国际刊名走 SJR 分区。"""
    if not journal_name:
        return 0
    n = _norm(journal_name)
    if n:
        if n in CSSCI:
            return 1
        if n in BEIDA:
            return 2
        if n in CSSCI_EXT:
            return 11
    k = _intl_key(journal_name)
    if k:
        q = _intl().get(k)
        if q in (1, 2):
            return 3
        if q in (3, 4):
            return 4
        if re.search(r"[A-Za-z]{4,}", journal_name):
            return 5
    return 0


def describe(journal_name: str) -> str:
    """返回可读标签（含国际分区）。"""
    t = tier_of(journal_name)
    k = _intl_key(journal_name)
    q = _intl().get(k) if k else None
    if t == 1:
        return u"CSSCI"
    if t == 2:
        return u"北大核心"
    if t == 11:
        return u"CSSCI扩展"
    if t == 3:
        return (u"国际 Q%d" % q) if q else u"国际·Q1/Q2"
    if t == 4:
        return (u"国际 Q%d" % q) if q else u"国际·Q3/Q4"
    if t == 5:
        return u"国际期刊"
    return u"—"


